def count_neighbors(grid, r, c, target_val):
    """Count orthogonal neighbors with same value"""
    h, w = len(grid), len(grid[0])
    count = 0
    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        nr, nc = r + dr, c + dc
        if 0 <= nr < h and 0 <= nc < w:
            if grid[nr][nc] == target_val:
                count += 1
    return count

def transform_grid(grid):
    """Keep cells with value V if they have >= 2 neighbors with same value"""
    if not grid or not grid[0]:
        return grid

    h, w = len(grid), len(grid[0])
    result = [[grid[r][c] for c in range(w)] for r in range(h)]

    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            neighbors = count_neighbors(grid, r, c, v)
            if neighbors < 2:
                result[r][c] = 0

    return result

